//! Read-path behavior: config, state and schedule reads, and their exit codes.
//!
//! These tests are hermetic — every one runs against a fixture config/state
//! tree under `XPST_CONFIG_DIR`, never against the developer's real `~/.xpst`.
//! The config goldens are generated by the Python engine
//! (`xtask/scripts/generate_config_goldens.py`), so the assertion here is a
//! real differential check: the Rust read path must reproduce Python's
//! `xpst config show` output byte for byte, including masking decisions.

use std::ffi::OsString;
use std::path::PathBuf;
use std::sync::{Mutex, MutexGuard};

use xpst_cli::run_with_io;

const CONFIG_YAML: &str = include_str!("fixtures/config-sample.yaml");
const CONFIG_MASKED: &str = include_str!("fixtures/config-sample.masked.json");
const CONFIG_RAW: &str = include_str!("fixtures/config-sample.raw.json");

/// Serializes tests that mutate `XPST_CONFIG_DIR`: it is process-global state.
static ENV_LOCK: Mutex<()> = Mutex::new(());

struct Fixture {
    dir: PathBuf,
    _guard: MutexGuard<'static, ()>,
}

impl Fixture {
    fn new(name: &str) -> Self {
        // The lock is held for the lifetime of the fixture so no other test
        // can observe a different XPST_CONFIG_DIR halfway through.
        let guard = ENV_LOCK.lock().unwrap_or_else(|poison| poison.into_inner());
        let dir = std::env::temp_dir().join(format!(
            "xpst-rust-p0-{name}-{}-{}",
            std::process::id(),
            unique_suffix()
        ));
        std::fs::create_dir_all(&dir).expect("create fixture dir");
        std::env::set_var("XPST_CONFIG_DIR", &dir);
        Self { dir, _guard: guard }
    }

    fn write(&self, name: &str, contents: &str) {
        std::fs::write(self.dir.join(name), contents).expect("write fixture file");
    }
}

impl Drop for Fixture {
    fn drop(&mut self) {
        std::env::remove_var("XPST_CONFIG_DIR");
        let _ = std::fs::remove_dir_all(&self.dir);
    }
}

fn unique_suffix() -> u128 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_nanos())
        .unwrap_or(0)
}

fn run(args: &[&str], stdout_is_tty: bool) -> (i32, String, String) {
    let mut argv: Vec<OsString> = vec![OsString::from("xpst")];
    argv.extend(args.iter().map(OsString::from));
    let mut out: Vec<u8> = Vec::new();
    let mut err: Vec<u8> = Vec::new();
    let code = run_with_io(argv, &mut out, &mut err, stdout_is_tty);
    (
        code,
        String::from_utf8_lossy(&out).into_owned(),
        String::from_utf8_lossy(&err).into_owned(),
    )
}

#[test]
fn config_show_reproduces_the_python_output_byte_for_byte() {
    let fixture = Fixture::new("show-masked");
    fixture.write("config.yaml", CONFIG_YAML);

    let (code, out, err) = run(&["config", "show"], false);
    assert_eq!(code, 0, "stderr: {err}");
    assert_eq!(
        out, CONFIG_MASKED,
        "masked output must match the Python engine"
    );
}

#[test]
fn config_show_raw_reproduces_the_python_output() {
    let fixture = Fixture::new("show-raw");
    fixture.write("config.yaml", CONFIG_YAML);

    let (code, out, err) = run(&["config", "show", "--raw"], false);
    assert_eq!(code, 0, "stderr: {err}");
    assert_eq!(out, CONFIG_RAW, "raw output must match the Python engine");
}

#[test]
fn raw_output_is_the_only_way_a_secret_reaches_stdout() {
    let fixture = Fixture::new("masking");
    fixture.write("config.yaml", CONFIG_YAML);

    let (_, masked, _) = run(&["config", "show"], false);
    assert!(
        !masked.contains("/fixture/.xpst/credentials/youtube_token.json"),
        "masked output leaked a credential path: {masked}"
    );
    let (_, raw, _) = run(&["config", "show", "--raw"], false);
    assert!(
        raw.contains("/fixture/.xpst/credentials/youtube_token.json"),
        "--raw must show the unmodified value"
    );
}

#[test]
fn config_show_human_output_is_yaml_on_a_tty() {
    let fixture = Fixture::new("show-yaml");
    fixture.write("config.yaml", CONFIG_YAML);

    let (code, out, err) = run(&["config", "show"], true);
    assert_eq!(code, 0, "stderr: {err}");
    assert!(out.starts_with("version: 4"), "expected YAML, got: {out}");
    assert!(
        !out.trim_start().starts_with('{'),
        "a TTY gets YAML, not JSON"
    );
    // Masking still applies to the human surface.
    assert!(!out.contains("youtube_token.json"));
}

#[test]
fn missing_config_exits_2_with_the_documented_json_error() {
    let _fixture = Fixture::new("missing-config");

    let (code, out, _err) = run(&["config", "show"], false);
    assert_eq!(code, 2, "config errors are exit code 2");
    let payload: serde_json::Value = serde_json::from_str(out.trim()).expect("valid JSON error");
    assert_eq!(payload["ok"], false);
    assert_eq!(payload["error"]["code"], "CONFIG_FILE_NOT_FOUND");
    assert!(payload["error"]["path"].as_str().is_some());
    assert!(payload["error"]["hint"]
        .as_str()
        .unwrap_or("")
        .contains("wizard"));
}

#[test]
fn invalid_yaml_exits_2_and_names_the_file() {
    let fixture = Fixture::new("invalid-yaml");
    fixture.write("config.yaml", "accounts: [\n");

    let (code, out, _err) = run(&["config", "show"], false);
    assert_eq!(code, 2);
    let payload: serde_json::Value = serde_json::from_str(out.trim()).expect("valid JSON error");
    assert_eq!(payload["error"]["code"], "INVALID_YAML");
    assert!(payload["error"]["message"]
        .as_str()
        .unwrap_or("")
        .contains("Invalid YAML in"));
}

#[test]
fn config_validate_reports_checks_and_exits_0_for_a_good_config() {
    let fixture = Fixture::new("validate-ok");
    fixture.write("config.yaml", CONFIG_YAML);

    let (code, out, err) = run(&["config", "validate"], false);
    assert_eq!(code, 0, "stderr: {err}");
    let payload: serde_json::Value = serde_json::from_str(out.trim()).expect("valid JSON");
    assert_eq!(payload["valid"], true);
    assert!(payload["checks"].as_array().expect("checks").len() >= 4);
}

#[test]
fn config_validate_flags_an_unrecognised_document() {
    let fixture = Fixture::new("validate-unknown");
    fixture.write("config.yaml", "totally_unrelated: 1\n");

    let (code, out, _err) = run(&["config", "validate"], false);
    assert_eq!(code, 2);
    let payload: serde_json::Value = serde_json::from_str(out.trim()).expect("valid JSON");
    assert_eq!(payload["valid"], false);
}

#[test]
fn doctor_reads_live_state_and_reports_an_absent_schedule_as_healthy() {
    let fixture = Fixture::new("doctor-ok");
    fixture.write("config.yaml", CONFIG_YAML);
    fixture.write(
        "state.json",
        r#"{"version": 2, "posted_videos": {"a": {"posted_to": {"x": {"id": "1", "deleted": false}}}}, "content_hashes": {"h": "a"}}"#,
    );
    // No schedule.json: the paused install looks exactly like this.

    let (code, out, err) = run(&["doctor"], false);
    assert_eq!(code, 0, "stderr: {err}\nstdout: {out}");
    let payload: serde_json::Value = serde_json::from_str(out.trim()).expect("valid JSON");
    assert_eq!(payload["ok"], true);
    assert_eq!(payload["engine"]["name"], "rust");
    assert_eq!(payload["engine"]["live_checks"], false);
    assert_eq!(payload["state"]["version"], 2);
    assert_eq!(payload["state"]["videos"], 1);
    assert_eq!(payload["schedule"]["present"], false);
    assert_eq!(payload["schedule"]["entries"], 0);
}

#[test]
fn doctor_fails_on_an_unreadable_config() {
    let _fixture = Fixture::new("doctor-missing");

    let (code, out, _err) = run(&["doctor"], false);
    assert_eq!(code, 2);
    let payload: serde_json::Value = serde_json::from_str(out.trim()).expect("valid JSON");
    assert_eq!(payload["ok"], false);
    assert_eq!(payload["config"]["readable"], false);
}

#[test]
fn doctor_refuses_a_future_state_schema() {
    let fixture = Fixture::new("doctor-future-state");
    fixture.write("config.yaml", CONFIG_YAML);
    fixture.write("state.json", r#"{"version": 99, "posted_videos": {}}"#);

    let (code, out, _err) = run(&["doctor"], false);
    assert_eq!(code, 2);
    let payload: serde_json::Value = serde_json::from_str(out.trim()).expect("valid JSON");
    assert_eq!(payload["ok"], false);
    assert!(payload["state"]["error"]
        .as_str()
        .unwrap_or("")
        .contains("Unsupported state schema version 99"));
}

#[test]
fn version_flag_matches_the_click_output_shape() {
    let (code, out, _err) = run(&["--version"], false);
    assert_eq!(code, 0);
    assert!(
        out.starts_with("xPST, version "),
        "expected Click's version shape, got: {out}"
    );
}
